1	package net.officefloor.hq.app.pool;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.HashMap;
8	import java.util.HashSet;
9	import java.util.LinkedHashMap;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.Set;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.stereotype.Repository;
15	
16	/** The pool store: each sheet's pools, in the order added, and their members. */
17	@Repository
18	public class Pools {
19	
20	    /** The shares of a balanced pool total exactly this. */
21	    public static final BigDecimal FULL = new BigDecimal("100.00");
22	
23	    private final JdbcTemplate jdbc;
24	
25	    public Pools(JdbcTemplate jdbc) {
26	        this.jdbc = jdbc;
27	    }
28	
29	    /** The deepest a chain of pools nests: a pool, a pool in it, and a pool in that. */
30	    public static final int MAX_DEPTH = 3;
31	
32	    /** The sheet's pools, in the order added, each with its members (people and pools) in the order added. A retired
33	     *  member (a retirement date set, whatever the date) counts their share toward the total; a member whose dates do not
34	     *  include the sheet's today is left out of it entirely (and has no cut). A pool that is a member of none
35	     *  has the sheet's pot; a pool that is a member of another has its cut there as its pot. While a pool has a pot,
36	     *  each member of it, if balanced, has a cut of it (see {@link #cuts}); otherwise no cut (""). */
37	    public List<PoolResponse> list(String sheetId) {
38	        return list(sheetId, null);
39	    }
40	
41	    /** The sheet's pools as {@link #list(String)}, with memberships' dates, holds and the pot judged on the date standing for
42	     *  the sheet's today (null: the sheet's today itself), as the as-of view shows them. */
43	    public List<PoolResponse> list(String sheetId, java.time.LocalDate on) {
44	        java.sql.Date day = on == null ? null : java.sql.Date.valueOf(on);
45	        Map<String, List<PoolResponse.Member>> members = new LinkedHashMap<>();
46	        for (String name : jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY seq", String.class, sheetId)) {
47	            members.put(name, new ArrayList<>());
48	        }
49	        jdbc.query("SELECT m.pool_name, m.person_id, p.name, m.share, p.retired_from, m.member_pool,"
50	                + " (m.from_date IS NULL OR m.from_date <= COALESCE(CAST(? AS DATE), s.today))"
51	                + " AND (m.to_date IS NULL OR m.to_date >= COALESCE(CAST(? AS DATE), s.today))"
52	                + " FROM pool_member m"
53	                + " LEFT JOIN person p ON p.id = m.person_id AND p.sheet_id = m.sheet_id"
54	                + " JOIN sheet s ON s.id = m.sheet_id"
55	                + " WHERE m.sheet_id = ? ORDER BY m.seq", rs -> {
56	                    List<PoolResponse.Member> list = members.get(rs.getString(1));
57	                    String sub = rs.getString(6);
58	                    String share = rs.getBigDecimal(4).setScale(2).toPlainString();
59	                    if (list == null) {
60	                        return;
61	                    }
62	                    boolean current = rs.getBoolean(7);
63	                    if (sub != null) {
64	                        list.add(new PoolResponse.Member(null, sub, sub, share, false, current, ""));
65	                    } else if (rs.getString(3) != null) {
66	                        list.add(new PoolResponse.Member(String.valueOf(rs.getLong(2)), null, rs.getString(3),
67	                                share, rs.getDate(5) != null, current, ""));
68	                    }
69	                }, day, day, sheetId);
70	        Set<String> crews = crewPools(sheetId, members);
71	        BigDecimal pot = day == null ? livePot(sheetId) : potOn(sheetId, day);
72	        Map<String, String> totals = new HashMap<>();
73	        Set<String> nested = new HashSet<>();
74	        members.forEach((name, list) -> {
75	            BigDecimal total = BigDecimal.ZERO.setScale(2);
76	            for (PoolResponse.Member m : list) {
77	                if (m.current()) {
78	                    total = total.add(new BigDecimal(m.share()));
79	                }
80	                if (m.memberPool() != null) {
81	                    nested.add(m.memberPool());
82	                }
83	            }
84	            totals.put(name, total.toPlainString());
85	        });
86	        Set<String> held = new HashSet<>(jdbc.queryForList("SELECT DISTINCT CAST(h.person_id AS VARCHAR) FROM person_hold h"
87	                + " JOIN sheet s ON s.id = h.sheet_id WHERE h.sheet_id = ? AND h.from_date <= COALESCE(CAST(? AS DATE), s.today)"
88	                + " AND (h.to_date IS NULL OR h.to_date >= COALESCE(CAST(? AS DATE), s.today))", String.class, sheetId, day, day));
89	        Map<String, List<PoolResponse.Member>> shown = new HashMap<>(members);
90	        for (String name : members.keySet()) {
91	            if (!nested.contains(name)) {
92	                share(name, pot, members, totals, held, shown, 0);
93	            }
94	        }
95	        List<PoolResponse> pools = new ArrayList<>();
96	        members.keySet().forEach(name -> pools.add(new PoolResponse(name, totals.get(name),
97	                new BigDecimal(totals.get(name)).compareTo(FULL) == 0, shown.get(name), crews.contains(name))));
98	        return pools;
99	    }
100	
101	    /** Adds each of the sheet's crews, in the order added and after the pools, as a pool of its name: the lead and then
102	     *  the members (in the order added) at equal shares, 100.00 split as patrons' shares are (each rounded half to even to
103	     *  two decimals, the remainder on the lead), every membership current. Returns the crews' names. */
104	    private Set<String> crewPools(String sheetId, Map<String, List<PoolResponse.Member>> members) {
105	        Set<String> crews = new HashSet<>();
106	        Map<String, List<PoolResponse.Member>> people = new LinkedHashMap<>();
107	        jdbc.query("SELECT c.name, c.lead_person_id, p.name, p.retired_from FROM crew c"
108	                + " LEFT JOIN person p ON p.id = c.lead_person_id AND p.sheet_id = c.sheet_id"
109	                + " WHERE c.sheet_id = ? ORDER BY c.seq", rs -> {
110	                    List<PoolResponse.Member> list = new ArrayList<>();
111	                    // A lead no longer on the sheet (moved away) is left out: the crew's members share it all.
112	                    if (rs.getString(3) != null) {
113	                        list.add(new PoolResponse.Member(String.valueOf(rs.getLong(2)), null, rs.getString(3), "",
114	                                rs.getDate(4) != null, true, ""));
115	                    }
116	                    people.put(rs.getString(1), list);
117	                }, sheetId);
118	        jdbc.query("SELECT m.crew_name, m.person_id, p.name, p.retired_from FROM crew_member m"
119	                + " JOIN person p ON p.id = m.person_id AND p.sheet_id = m.sheet_id"
120	                + " WHERE m.sheet_id = ? ORDER BY m.seq", rs -> {
121	                    List<PoolResponse.Member> list = people.get(rs.getString(1));
122	                    if (list != null) {
123	                        list.add(new PoolResponse.Member(String.valueOf(rs.getLong(2)), null, rs.getString(3), "",
124	                                rs.getDate(4) != null, true, ""));
125	                    }
126	                }, sheetId);
127	        people.forEach((name, list) -> {
128	            if (members.containsKey(name) || list.isEmpty()) {
129	                return;
130	            }
131	            BigDecimal each = FULL.divide(BigDecimal.valueOf(list.size()), 2, RoundingMode.HALF_EVEN);
132	            BigDecimal lead = FULL.subtract(each.multiply(BigDecimal.valueOf(list.size() - 1)));
133	            List<PoolResponse.Member> shared = new ArrayList<>();
134	            for (int i = 0; i < list.size(); i++) {
135	                PoolResponse.Member m = list.get(i);
136	                shared.add(new PoolResponse.Member(m.personId(), null, m.name(), (i == 0 ? lead : each).toPlainString(),
137	                        m.retired(), true, ""));
138	            }
139	            members.put(name, shared);
140	            crews.add(name);
141	        });
142	        return crews;
143	    }
144	
145	    /** The sheet's pot now, at two decimals; null when none. */
146	    private BigDecimal livePot(String sheetId) {
147	        List<BigDecimal> pots = jdbc.queryForList("SELECT pot FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
148	        return pots.isEmpty() || pots.get(0) == null ? null : pots.get(0).setScale(2);
149	    }
150	
151	    /** The sheet's pot as it stood at the end of the date: the latest set by then (see the as-of view); null when none. */
152	    private BigDecimal potOn(String sheetId, java.sql.Date day) {
153	        List<String> set = jdbc.queryForList("SELECT setting_value FROM plain_setting_history WHERE sheet_id = ?"
154	                + " AND setting_key = ? AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", String.class, sheetId,
155	                net.officefloor.hq.app.setting.Settings.POT, day);
156	        String latest = set.isEmpty() ? null : set.get(set.size() - 1);
157	        return latest == null || latest.isEmpty() ? null : new BigDecimal(latest).setScale(2);
158	    }
159	
160	    /** Gives the pool's members their cuts of its pot, when it has one and is balanced, and passes each member pool's
161	     *  cut down to it as that pool's pot. */
162	    private static void share(String name, BigDecimal pot, Map<String, List<PoolResponse.Member>> members,
163	            Map<String, String> totals, Set<String> held, Map<String, List<PoolResponse.Member>> shown, int depth) {
164	        if (pot == null || depth > MAX_DEPTH || new BigDecimal(totals.get(name)).compareTo(FULL) != 0) {
165	            return;
166	        }
167	        List<PoolResponse.Member> withCuts = cuts(members.get(name), pot, held);
168	        shown.put(name, withCuts);
169	        for (PoolResponse.Member m : withCuts) {
170	            if (m.memberPool() != null && members.containsKey(m.memberPool()) && m.current()) {
171	                share(m.memberPool(), new BigDecimal(m.cut()), members, totals, held, shown, depth + 1);
172	            }
173	        }
174	    }
175	
176	    /** The members with their cuts of the pot: the pot times their share divided by the shares of the members with a
177	     *  cut added up, rounded half to even to two decimals (a retired member, or a person held on the sheet's today,
178	     *  cuts 0.00, their share spread over the others in proportion to theirs); the remainder, the pot minus the cuts added up, goes to the member with a cut with the smallest
179	     *  non-zero cut (the latest added on a tie; with no non-zero cut, the last member with a cut), so the cuts total exactly the pot. With no member left with a cut, each cuts 0.00 —
180	     *  unless every member is retired, when none has a cut ("").
181	     *  A member whose dates do not include the sheet's today has no cut at all (""). */
182	    static List<PoolResponse.Member> cuts(List<PoolResponse.Member> members, BigDecimal pot, Set<String> held) {
183	        BigDecimal[] cuts = new BigDecimal[members.size()];
184	        boolean[] cutting = new boolean[members.size()];
185	        BigDecimal shares = BigDecimal.ZERO;
186	        boolean allRetired = true;
187	        for (int i = 0; i < members.size(); i++) {
188	            PoolResponse.Member m = members.get(i);
189	            if (m.current() && !m.retired()) {
190	                allRetired = false;
191	            }
192	            cutting[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
193	            if (cutting[i]) {
194	                shares = shares.add(new BigDecimal(m.share()));
195	            }
196	        }
197	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
198	        int smallest = -1;
199	        int last = -1;
200	        for (int i = 0; i < members.size(); i++) {
201	            PoolResponse.Member m = members.get(i);
202	            BigDecimal share = new BigDecimal(m.share());
203	            cuts[i] = !m.current() || allRetired ? null : !cutting[i] || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
204	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
205	            if (cuts[i] != null) {
206	                sum = sum.add(cuts[i]);
207	            }
208	            if (cutting[i]) {
209	                last = i;
210	                if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
211	                    smallest = i;
212	                }
213	            }
214	        }
215	        int remainder = smallest >= 0 ? smallest : last;
216	        if (remainder >= 0 && shares.signum() != 0) {
217	            cuts[remainder] = cuts[remainder].add(pot.subtract(sum));
218	        }
219	        List<PoolResponse.Member> withCuts = new ArrayList<>();
220	        for (int i = 0; i < members.size(); i++) {
221	            PoolResponse.Member m = members.get(i);
222	            withCuts.add(new PoolResponse.Member(m.personId(), m.memberPool(), m.name(), m.share(), m.retired(), m.current(),
223	                    cuts[i] == null ? "" : cuts[i].toPlainString()));
224	        }
225	        return withCuts;
226	    }
227	
228	    /** Whether the sheet has a pool of the name: one added as a pool, or a crew (every crew is also a pool). */
229	    public boolean contains(String sheetId, String name) {
230	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool WHERE sheet_id = ? AND name = ?", Integer.class, sheetId, name);
231	        return n != null && n > 0 || isCrew(sheetId, name);
232	    }
233	
234	    /** Whether the pool of the name is a crew's: its members are the crew's lead and members, never added as a pool's. */
235	    public boolean isCrew(String sheetId, String name) {
236	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM crew WHERE sheet_id = ? AND name = ?", Integer.class, sheetId, name);
237	        return n != null && n > 0;
238	    }
239	
240	    /** Whether the person is a member of the pool. */
241	    public boolean hasMember(String sheetId, String pool, long personId) {
242	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool_member WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
243	                Integer.class, sheetId, pool, personId);
244	        return n != null && n > 0;
245	    }
246	
247	    /** Adds a pool to the sheet. */
248	    public void add(String sheetId, String name) {
249	        jdbc.update("INSERT INTO pool (sheet_id, name) VALUES (?, ?)", sheetId, name);
250	    }
251	
252	    /** The pool the pool is a member of, or null when it is a member of none. */
253	    public String parentOf(String sheetId, String pool) {
254	        List<String> parents = jdbc.queryForList("SELECT pool_name FROM pool_member WHERE sheet_id = ? AND member_pool = ?",
255	                String.class, sheetId, pool);
256	        return parents.isEmpty() ? null : parents.get(0);
257	    }
258	
259	    /** The pools that are members of the pool. */
260	    public List<String> subPoolsOf(String sheetId, String pool) {
261	        return jdbc.queryForList("SELECT member_pool FROM pool_member WHERE sheet_id = ? AND pool_name = ?"
262	                + " AND member_pool IS NOT NULL ORDER BY seq", String.class, sheetId, pool);
263	    }
264	
265	    /** Adds the person (memberPool null) or the other pool (personId null) to the pool with the share and the optional from-
266	     *  and to-dates of the membership. */
267	    public void addMember(String sheetId, String pool, Long personId, String memberPool, BigDecimal share,
268	            LocalDate from, LocalDate to) {
269	        jdbc.update("INSERT INTO pool_member (sheet_id, pool_name, person_id, member_pool, share, from_date, to_date)"
270	                + " VALUES (?, ?, ?, ?, ?, ?, ?)", sheetId, pool, personId, memberPool, share, from, to);
271	    }
272	}
