package net.officefloor.hq.app.pool;

import java.util.List;

/** A pool as shown: its members, the total of their shares (a retired member's share counted as given) and whether
 *  that total is exactly 100.00; crew: whether it is a crew's pool (its members the crew's lead and members). */
public record PoolResponse(String name, String totalShare, boolean balanced, List<Member> members, boolean crew) {

    /** A member: the person's id and name (or, for a pool that is a member, personId null, memberPool and name its
     *  name), their share (two decimals), whether a retirement date is set, whether the membership's dates include the sheet's today (when not, the member
     *  is left out of the total and has no cut) and their cut of the pool's pot (two
     *  decimals; "" when the pool is not balanced or has no pot). */
    public record Member(String personId, String memberPool, String name, String share, boolean retired, boolean current,
            String cut) {
    }
}
-- The sheet's pools, by name, in the order added.
CREATE TABLE pool (
    seq      BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)  NOT NULL,
    name     VARCHAR(2000) NOT NULL,
    UNIQUE (sheet_id, name)
);

-- A pool's members: a person of the sheet with a share percent (more than 0.00, at most 100.00), in
-- the order added. A person is in a pool at most once, but may be in several pools.
CREATE TABLE pool_member (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL,
    pool_name VARCHAR(2000) NOT NULL,
    person_id BIGINT        NOT NULL,
    share     DECIMAL(5, 2) NOT NULL,
    UNIQUE (sheet_id, pool_name, person_id)
);
-- The sheet's pot: each member of a balanced pool shows their cut of it. NULL: none. Not dated.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(14, 2);
-- A pool membership may carry a from-date and a to-date (each optional, inclusive; the to-date never before the
-- from-date). A member whose dates do not include the sheet's today is left out of its pool entirely: not in the
-- total share, not in the balance, no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- The day a SNAPSHOT line was taken on: the sheet's today it moved to (set_on is the day being left).
-- Null for lines kept before it was recorded.
ALTER TABLE person_snapshot ADD COLUMN taken_on DATE;
